var n=`0952-yakisoba`;var a=`world-0952`;var s=`JP`;var t=`east-asia`;var o=4;var r=27;var l={en:`Yakisoba`,ua:`Якісоба`};var d={en:`Yakisoba is a Japan dish made with chow mein noodles, pork belly, white cabbage, carrot. This home-scale recipe assigns measured ingredients to the steps where they are used. Uses chow mein noodles instead of Japanese yakisoba noodles.`,ua:`Якісоба, страва кухні країни Японія. Основні складники: локшина чоу-мейн, свиняча грудинка, білоголова капуста, морква. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Замість японської локшини якісоба використано чоу-мейн.`};var g=[{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`chow-mein-noodles`,410,`g`],[`water`,1e3,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`pork-belly`,330,`g`],[`white-cabbage`,280,`g`],[`carrot`,170,`g`],[`yellow-onion`,150,`g`],[`canola-oil`,50,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 8 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 8 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:8,i:[[`worcestershire-sauce`,60,`ml`],[`light-soy-sauce`,35,`ml`],[`ketchup`,40,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pickled-ginger`,35,`g`],[`aonori`,8,`g`]]}];var h={slug:n,id:a,country:`JP`,region:t,servings:4,minutes:27,title:l,text:d,steps:g};export{s as country,h as default,a as id,r as minutes,t as region,o as servings,n as slug,g as steps,d as text,l as title};